package com.shopsphere.filter;import com.shopsphere.model.User;import jakarta.servlet.*;import jakarta.servlet.annotation.WebFilter;import jakarta.servlet.http.*;import java.io.*;@WebFilter("/admin/*")public class AdminFilter implements Filter{public void doFilter(ServletRequest a,ServletResponse b,FilterChain c)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)a;HttpSession s=r.getSession(false);User u=s==null?null:(User)s.getAttribute("user");if(u==null||!"ADMIN".equalsIgnoreCase(u.getRole())){((HttpServletResponse)b).sendError(403,"Admin access required");return;}c.doFilter(a,b);}}
